/* ==========================================================
 * Student Report Card Management System - Ultra Modern UI
 * ========================================================== */

@import url('https://fonts.googleapis.com/css2?family=Vazirmatn:wght@300;400;500;600;700;800&display=swap');

:root {
    --primary: #2563eb;
    --primary-hover: #1d4ed8;
    --bg-body: #f8fafc;
    --bg-card: #ffffff;
    --bg-header: #ffffff;
    --text-main: #0f172a;
    --text-muted: #64748b;
    --border-color: #e2e8f0;
    --table-header: #f1f5f9;
    --table-hover: #f8fafc;
    --input-bg: #ffffff;
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

html.dark, body.dark, .dark {
    --primary: #3b82f6;
    --primary-hover: #60a5fa;
    --bg-body: #0b1120;
    --bg-card: #1e293b;
    --bg-header: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --table-header: #0f172a;
    --table-hover: #162032;
    --input-bg: #0f172a;
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.3);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.5);
}

* {
    box-sizing: border-box;
    font-family: 'Vazirmatn', Tahoma, sans-serif;
}

body {
    margin: 0;
    padding: 0;
    background-color: var(--bg-body);
    color: var(--text-main);
    transition: background-color 0.25s ease, color 0.25s ease;
}

a {
    text-decoration: none;
    color: inherit;
}

/* Utilities */
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.justify-center { justify-content: center; }
.gap-1 { gap: 0.25rem; }
.gap-2 { gap: 0.5rem; }
.gap-3 { gap: 0.75rem; }
.gap-4 { gap: 1rem; }
.gap-6 { gap: 1.5rem; }
.grid { display: grid; }
.grid-cols-1 { grid-template-columns: repeat(1, minmax(0, 1fr)); }
.grid-cols-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-cols-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }

@media (max-width: 768px) {
    .grid-cols-2, .grid-cols-3, .grid-cols-4 { grid-template-columns: repeat(1, minmax(0, 1fr)); }
    .sidebar { width: 100% !important; border-left: none !important; border-bottom: 1px solid var(--border-color); }
    .flex-1.flex { flex-direction: column; }
}

.min-h-screen { min-height: 100vh; }
.p-4 { padding: 1rem; }
.p-6 { padding: 1.5rem; }
.py-2 { padding-top: 0.5rem; padding-bottom: 0.5rem; }
.px-4 { padding-left: 1rem; padding-right: 1rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-6 { margin-bottom: 1.5rem; }
.mt-4 { margin-top: 1rem; }
.w-full { width: 100%; }

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.6rem 1.25rem;
    border-radius: 0.625rem;
    font-weight: 600;
    font-size: 0.875rem;
    cursor: pointer;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    border: none;
    box-shadow: var(--shadow-sm);
}
.btn:active { transform: scale(0.98); }
.btn-primary { background-color: var(--primary); color: #ffffff; }
.btn-primary:hover { background-color: var(--primary-hover); box-shadow: var(--shadow-md); }
.btn-secondary { background-color: #64748b; color: #ffffff; }
.btn-secondary:hover { background-color: #475569; }
.btn-success { background-color: #10b981; color: #ffffff; }
.btn-success:hover { background-color: #059669; box-shadow: var(--shadow-md); }
.btn-danger { background-color: #ef4444; color: #ffffff; }
.btn-danger:hover { background-color: #dc2626; box-shadow: var(--shadow-md); }
.btn-outline { background-color: transparent; border: 1.5px solid var(--border-color); color: var(--text-main); }
.btn-outline:hover { background-color: rgba(100, 116, 139, 0.1); border-color: var(--primary); color: var(--primary); }

/* Navbar & Sidebar */
.navbar {
    background-color: var(--bg-header);
    border-bottom: 1px solid var(--border-color);
    box-shadow: var(--shadow-sm);
    transition: background-color 0.25s, border-color 0.25s;
}

.sidebar {
    background-color: var(--bg-card);
    border-left: 1px solid var(--border-color);
    transition: background-color 0.25s, border-color 0.25s;
}

.sidebar-item {
    display: flex;
    align-items: center;
    padding: 0.7rem 1.1rem;
    border-radius: 0.625rem;
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--text-main);
    transition: all 0.2s;
    margin-bottom: 0.2rem;
}
.sidebar-item:hover {
    background-color: rgba(37, 99, 235, 0.08);
    color: var(--primary);
    transform: translateX(-3px);
}
.sidebar-item.active {
    background-color: var(--primary);
    color: #ffffff !important;
    font-weight: 700;
    box-shadow: var(--shadow-md);
}

/* Cards */
.card {
    background-color: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 1rem;
    padding: 1.5rem;
    box-shadow: var(--shadow-md);
    transition: background-color 0.25s, border-color 0.25s, box-shadow 0.25s;
}
.card:hover {
    box-shadow: var(--shadow-lg);
}

/* Tables */
.table-container {
    width: 100%;
    overflow-x: auto;
    border-radius: 0.75rem;
    border: 1px solid var(--border-color);
}
table {
    width: 100%;
    border-collapse: collapse;
    text-align: right;
}
th, td {
    padding: 0.85rem 1rem;
    border-bottom: 1px solid var(--border-color);
    font-size: 0.875rem;
}
th {
    font-weight: 700;
    background-color: var(--table-header);
    color: var(--text-muted);
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 0.5px;
}
tr:last-child td { border-bottom: none; }
tr:hover td {
    background-color: var(--table-hover);
}

/* Form Inputs */
.form-input, .form-select, .form-textarea {
    width: 100%;
    padding: 0.65rem 0.9rem;
    border: 1.5px solid var(--border-color);
    border-radius: 0.625rem;
    background-color: var(--input-bg);
    color: var(--text-main);
    font-size: 0.875rem;
    margin-top: 0.3rem;
    transition: border-color 0.2s, box-shadow 0.2s;
}
.form-input:focus, .form-select:focus, .form-textarea:focus {
    outline: none;
    border-color: var(--primary);
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

/* Wizard Steps */
.wizard-steps {
    display: flex;
    justify-content: space-between;
    margin-bottom: 2rem;
    background: var(--bg-card);
    padding: 0.5rem;
    border-radius: 0.75rem;
    border: 1px solid var(--border-color);
}
.wizard-step {
    flex: 1;
    text-align: center;
    padding: 0.75rem;
    border-bottom: 3px solid var(--border-color);
    color: var(--text-muted);
    font-weight: 600;
    transition: all 0.2s;
}
.wizard-step.active {
    border-color: var(--primary);
    color: var(--primary);
    font-weight: 800;
}
.wizard-step.completed {
    border-color: #10b981;
    color: #10b981;
}

/* Badges */
.badge {
    display: inline-flex;
    align-items: center;
    padding: 0.3rem 0.75rem;
    border-radius: 9999px;
    font-size: 0.75rem;
    font-weight: 700;
}
.badge-success { background-color: rgba(16, 185, 129, 0.15); color: #059669; border: 1px solid rgba(16, 185, 129, 0.3); }
.badge-warning { background-color: rgba(245, 158, 11, 0.15); color: #d97706; border: 1px solid rgba(245, 158, 11, 0.3); }
.badge-danger { background-color: rgba(239, 68, 68, 0.15); color: #dc2626; border: 1px solid rgba(239, 68, 68, 0.3); }
.badge-info { background-color: rgba(59, 130, 246, 0.15); color: #2563eb; border: 1px solid rgba(59, 130, 246, 0.3); }

/* Print optimization */
@media print {
    .sidebar, .navbar, footer, .no-print {
        display: none !important;
    }
    body, .card {
        background-color: #ffffff !important;
        color: #000000 !important;
        border: none !important;
        box-shadow: none !important;
    }
    main { padding: 0 !important; overflow: visible !important; }
}

