/**
 * Main Interactive JS script
 */

document.addEventListener('DOMContentLoaded', function () {
    // Theme Switcher
    const themeToggleBtn = document.getElementById('themeToggleBtn');
    if (themeToggleBtn) {
        themeToggleBtn.addEventListener('click', function () {
            const htmlEl = document.documentElement;
            const bodyEl = document.body;
            const isDark = htmlEl.classList.contains('dark') || bodyEl.classList.contains('dark');
            if (isDark) {
                htmlEl.classList.remove('dark');
                bodyEl.classList.remove('dark');
                localStorage.setItem('theme', 'light');
            } else {
                htmlEl.classList.add('dark');
                bodyEl.classList.add('dark');
                localStorage.setItem('theme', 'dark');
            }
        });
    }

    // Apply stored theme if set
    const storedTheme = localStorage.getItem('theme');
    if (storedTheme === 'dark') {
        document.documentElement.classList.add('dark');
        document.body.classList.add('dark');
    } else if (storedTheme === 'light') {
        document.documentElement.classList.remove('dark');
        document.body.classList.remove('dark');
    }

    // Auto-hide alert boxes after 5 seconds
    const alerts = document.querySelectorAll('.mb-4.p-4.rounded-lg.border');
    alerts.forEach(alert => {
        setTimeout(() => {
            alert.style.opacity = '0';
            alert.style.transition = 'opacity 0.5s ease';
            setTimeout(() => alert.remove(), 500);
        }, 5000);
    });
});

/**
 * Ajax search helper for tables
 */
function liveSearchTable(inputId, tableId) {
    const input = document.getElementById(inputId);
    if (!input) return;
    input.addEventListener('keyup', function () {
        const filter = input.value.toLowerCase();
        const table = document.getElementById(tableId);
        const rows = table.getElementsByTagName('tr');
        for (let i = 1; i < rows.length; i++) {
            let rowText = rows[i].textContent || rows[i].innerText;
            if (rowText.toLowerCase().indexOf(filter) > -1) {
                rows[i].style.display = '';
            } else {
                rows[i].style.display = 'none';
            }
        }
    });
}
